content.css:
.mapa3d {
  position: relative;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
}
.mapa3d canvas {
  display: block;
  cursor: grab;
  touch-action: none;
}
.mapa3d canvas:active {
  cursor: grabbing;
}
.mapa3d .legenda {
  position: absolute;
  left: 12px;
  bottom: 10px;
  width: 150px;
  pointer-events: none;
  color: #64748B;
  font-size: 10px;
}
.mapa3d .legenda .titulo {
  color: #1B2A4A;
  font-weight: 600;
  margin-bottom: 4px;
}
.mapa3d .legenda .barra {
  height: 8px;
  border-radius: 4px;
}
.mapa3d .legenda .escala {
  display: flex;
  justify-content: space-between;
  margin-top: 2px;
}
.mapa3d .aviso {
  position: absolute;
  top: 10px;
  left: 0;
  right: 0;
  text-align: center;
  color: #64748B;
  font-size: 11px;
  pointer-events: none;
}
